INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einer Bedarfsanalyse?', 2, '[{"text": "Ermittlung von Anforderungen", "correct": true, "because": "Basis für Projekte"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Bedarfsanalyse?', 3, '[{"text": "Projektanforderungen definieren", "correct": true, "because": "Grundlage für Entwicklung"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design optimieren", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zur Bedarfsanalyse?', 5, '[{"text": "Interviews", "correct": true, "because": "Direkte Bedarfserhebung"}, {"text": "Fragebögen", "correct": true, "because": "Systematische Datensammlung"}, {"text": "Hardwaretests", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Bedarfsanalyse ist der erste Schritt im Projektmanagement. b) Sie ist nur für Softwareentwicklung relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Systemintegration"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Bedarfsanalyse?', 4, '[{"text": "Stakeholder-Anforderungen", "correct": false, "because": "Kern der Analyse"}, {"text": "Projektziele", "correct": false, "because": "Grundlage"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Bedarfsanalyse Stakeholder einbezieht?', 2, '[{"text": "Ja", "correct": true, "because": "Bedürfnisse ermitteln"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine Bedarfsanalyse?', 3, '[{"text": "Workshops", "correct": true, "because": "Direkte Zusammenarbeit"}, {"text": "Hardwaretests", "correct": false, "because": "Anderer Fokus"}, {"text": "Marketingkampagnen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Durchführung einer Bedarfsanalyse?', 5, '[{"text": "Anforderungen sammeln", "correct": true, "because": "Erhebung"}, {"text": "Prioritäten setzen", "correct": true, "because": "Reihenfolge festlegen"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Bedarfsanalyse verbessert die Projektplanung. b) Sie ist nur für große Projekte nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Bedarfsanalyse unwichtig?', 4, '[{"text": "Anforderungsdokumentation", "correct": false, "because": "Ergebnis"}, {"text": "Stakeholder-Einbindung", "correct": false, "because": "Pflicht"}, {"text": "Farbauswahl", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Bedarfsanalyse einmalig?', 2, '[{"text": "Nein", "correct": true, "because": "Kann iterativ sein"}, {"text": "Ja", "correct": false, "because": "Flexibel anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Bedarfsanalyse für Fachinformatiker?', 4, '[{"text": "Klare Projektziele", "correct": true, "because": "Richtung vorgeben"}, {"text": "Weniger Missverständnisse", "correct": true, "because": "Anforderungen klar"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Bedarfsanalyse nur für Kundenprojekte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Projekte"}, {"text": "Ja", "correct": false, "because": "Breiter anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Bedarfsanalyse?', 3, '[{"text": "Stakeholder-Bedürfnisse", "correct": true, "because": "Kern der Analyse"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Bedarfsanalyse kann Workshops nutzen. b) Sie ist nur für Software relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Hardwareprojekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Bedarfsanalyse?', 5, '[{"text": "Unklare Anforderungen", "correct": true, "because": "Fehlende Klarheit"}, {"text": "Projektverzögerungen", "correct": true, "because": "Missverständnisse"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei der Bedarfsanalyse?', 3, '[{"text": "Anforderungen dokumentieren", "correct": true, "because": "Basis für Umsetzung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Bedarfsanalyse digital durchgeführt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Tools wie Umfragen"}, {"text": "Nein", "correct": false, "because": "Flexibel möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug könnte ein Fachinformatiker für die Bedarfsanalyse nutzen?', 4, '[{"text": "JIRA", "correct": true, "because": "Anforderungsmanagement"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
